import glob, re, sys
files = sorted(glob.glob("cht-fix/SLUS-99999*.cht"))
if not files:
    sys.exit("no cht-fix/SLUS-99999.cht or SLUS-99999-<hash>.cht")
keys = {"Type", "Activation", "Description", "Author", "Option", "OptionRange",
        "OverrideAspectRatio", "OverrideCPUOverclock", "DisableWidescreenRendering",
        "Enable8MBRAM", "DisallowForAchievements", "Ignore"}
errors, codes, current, lines = [], {}, None, []
for raw in open(files[0], encoding="utf-8"):
    line = raw.strip()
    if not line or line[0] in ";#":
        continue
    header = re.fullmatch(r"\[(.+)\]", line)
    if header:
        current = codes.setdefault(header.group(1), {"meta": {}, "code": []})
        continue
    if current is None:
        errors.append("content before first [Code Name]: " + line)
        continue
    pair = re.fullmatch(r"([A-Za-z0-9_]+)\s*=\s*(.*)", line)
    if pair:
        if pair.group(1) not in keys:
            errors.append("unknown key " + pair.group(1))
        current["meta"][pair.group(1)] = pair.group(2).strip()
    elif re.fullmatch(r"[0-9A-Fa-f?]{8} [0-9A-Fa-f?]{1,8}", line):
        current["code"].append(line.upper())
        lines.append(line.upper())
    else:
        errors.append("bad line " + line)
for name, code in codes.items():
    meta = code["meta"]
    if meta.get("Type") != "Gameshark":
        errors.append(f"[{name}] Type must be Gameshark")
    if meta.get("Activation") not in {"Manual", "EndFrame"}:
        errors.append(f"[{name}] Activation {meta.get('Activation')!r} is not Manual or EndFrame")
    if any("?" in c for c in code["code"]) and not ({"Option", "OptionRange"} & set(meta)):
        errors.append(f"[{name}] uses ? without Option or OptionRange")
    if not code["code"]:
        errors.append(f"[{name}] has no code lines")
if "8008DA9A 0C00" not in lines:
    errors.append("8008DA9A 0C00 (OCOO with letter O fixed) missing")
if "80010002 00??" not in lines:
    errors.append("80010002 00?? missing")
ranges = [c["meta"].get("OptionRange", "").replace(" ", "") for c in codes.values()]
if "1:60" not in ranges:
    errors.append("no OptionRange = 1:60")
print("\n".join(errors) or "OK " + files[0])
sys.exit(1 if errors else 0)
